// Pull the result JSON out of the script's stdout so the execution log
// shows counts and payloads at a glance.
const out = [];
for (const item of $input.all()) {
  const stdout = item.json.stdout || '';
  const start = stdout.indexOf('{');
  let summary;
  try {
    summary = start >= 0 ? JSON.parse(stdout.slice(start)) : { note: 'no JSON in stdout', stderr: item.json.stderr || '' };
  } catch (err) {
    summary = { note: 'could not parse stdout', error: String(err), stdout: stdout.slice(0, 500) };
  }
  out.push({ json: summary });
}
return out;
